func MapBounded[T any, R any](
	parent context.Context,
	concurrency int,
	items []T,
	fn func(context.Context, T) (R, error),
) ([]R, error) {
	if concurrency <= 0 {
		return nil, fmt.Errorf("concurrency must be >= 1")
	}
	ctx, cancel := context.WithCancel(parent)
	defer cancel()

	jobs := make(chan int)
	results := make([]R, len(items))
	var (
		errOnce sync.Once
		firstErr error
		wg      sync.WaitGroup
	)

	for w := 0; w < concurrency; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for idx := range jobs {
				res, err := fn(ctx, items[idx])
				if err != nil {
					errOnce.Do(func() {
						firstErr = err
						cancel()
					})
					continue
				}
