func CopyZipEntryBounded(
	dst io.Writer,
	f *zip.File,
	maxEntryBytes int64,
	totalExtracted *int64,
	maxTotalBytes int64,
) error {
	if maxEntryBytes <= 0 || maxTotalBytes <= 0 {
		return errors.New("byte limits must be positive")
	}
	if f.UncompressedSize64 > uint64(maxEntryBytes) {
		return fmt.Errorf("declared entry size %d exceeds limit %d", f.UncompressedSize64, maxEntryBytes)
	}
	rc, err := f.Open()
	if err != nil {
		return err
	}
	defer rc.Close()

	remainingTotal := maxTotalBytes - *totalExtracted
	capBytes := maxEntryBytes
	if remainingTotal < capBytes {
		capBytes = remainingTotal
	}
	if capBytes < 0 {
		return errors.New("archive total extraction quota exhausted")
	}

