const upsertRollupSQL = `
INSERT INTO metric_hourly_rollups (tenant_id, metric_name, bucket_hour, sample_count, sum_value)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (tenant_id, metric_name, bucket_hour)
