const MAX_MERGE_DEPTH = 8;

function isPlainObject(val: unknown): val is Record<string, unknown> {
  if (typeof val !== "object" || val === null || Array.isArray(val)) {
    return false;
  }
  const proto = Object.getPrototypeOf(val);
  return proto === Object.prototype || proto === null;
}

export function mergeSafePreferences(
  base: Record<string, unknown>,
  patch: Record<string, unknown>,
  depth = 0,
): Record<string, unknown> {
  if (depth > MAX_MERGE_DEPTH) {
    throw new RangeError("Preference nesting exceeds maximum depth");
  }
  const out: Record<string, unknown> = { ...base };
  for (const key of Object.keys(patch)) {
    if (FORBIDDEN_KEYS.has(key)) {
      throw new Error(`Disallowed preference key: ${key}`);
    }
    const nextVal = patch[key];
    const curVal = Object.hasOwn(out, key) ? out[key] : undefined;
